begin;
create extension if not exists pgtap with schema extensions;
select plan(20);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_user_meta_data,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','99000000-0000-4000-8000-000000000001','authenticated','authenticated','appointments-owner@example.test','','now','{"display_name":"Dr. Ana Reyes"}',now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','99000000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"99000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.create_business('appointments-test','Appointments Test Legal','Appointments Test','sole_proprietorship','services','{"city":"Manila"}');select set_config('test.app_org',(select id::text from public.organizations where slug='appointments-test'),true);select set_config('test.app_branch',(select id::text from public.branches where organization_id=current_setting('test.app_org')::uuid and code='main'),true);
select is(public.can_business_permission(current_setting('test.app_org')::uuid,'appointments.manage'),true,'Owner receives appointment management permission');
select throws_ok($$select public.save_appointment(current_setting('test.app_org')::uuid,null,current_setting('test.app_branch')::uuid,gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),current_date,'09:00','10:00','scheduled','')$$,'42501','Permission denied.','Appointment writes require the enabled module');
reset role;insert into public.subscriptions(organization_id,provider,plan_key,status)values(current_setting('test.app_org')::uuid,'internal','growth','trialing');set local role authenticated;select set_config('request.jwt.claim.sub','99000000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"99000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.set_business_module_state(current_setting('test.app_org')::uuid,'product_catalog',true,'{}');select public.set_business_module_state(current_setting('test.app_org')::uuid,'crm',true,'{}');
select lives_ok($$select public.set_business_module_state(current_setting('test.app_org')::uuid,'appointments',true,'{"slot_minutes":30,"prevent_staff_conflicts":true,"prevent_customer_conflicts":false}')$$,'Appointments activates with CRM and catalog dependencies');
select results_eq($$select display_name,status from public.appointment_staff where organization_id=current_setting('test.app_org')::uuid$$,$$select 'Dr. Ana Reyes'::text,'active'::text$$,'Active Business members become schedulable staff');
select set_config('test.app_staff',(select id::text from public.appointment_staff where organization_id=current_setting('test.app_org')::uuid),true);
select set_config('test.app_service',public.save_catalog_product(current_setting('test.app_org')::uuid,null,null,'service','Consultation','',null,null,'piece',500,0,'exempt',0,'active',false,'[{"name":"Default","sku":"SERVICE-APPT","barcode":"","attributes":{},"status":"active"}]','[]')::text,true);
select set_config('test.app_customer1',public.save_crm_customer(current_setting('test.app_org')::uuid,null,current_setting('test.app_branch')::uuid,'Maria Santos','09171234567','','{}',null,null,'retail','{}','')::text,true);
select set_config('test.app_customer2',public.save_crm_customer(current_setting('test.app_org')::uuid,null,current_setting('test.app_branch')::uuid,'Jose Cruz','09181234567','','{}',null,null,'retail','{}','')::text,true);
select set_config('test.app1',public.save_appointment(current_setting('test.app_org')::uuid,null,current_setting('test.app_branch')::uuid,current_setting('test.app_customer1')::uuid,current_setting('test.app_service')::uuid,current_setting('test.app_staff')::uuid,current_date+1,'09:00','10:00','scheduled','First visit')::text,true);
select results_eq($$select appointment_number,status,appointment_date,start_time,end_time from public.appointments where id=current_setting('test.app1')::uuid$$,$$select 'APT-'||extract(year from current_date)::integer||'-000001','scheduled'::text,current_date+1,time'09:00',time'10:00'$$,'Appointment stores its customer service staff date and local time');
select throws_ok($$select public.save_appointment(current_setting('test.app_org')::uuid,null,current_setting('test.app_branch')::uuid,current_setting('test.app_customer2')::uuid,current_setting('test.app_service')::uuid,current_setting('test.app_staff')::uuid,current_date+1,'09:30','10:30','scheduled','Conflict')$$,'P0001','Staff member already has an overlapping appointment.','Configured staff conflict prevention rejects overlap');
select set_config('test.app_adjacent',public.save_appointment(current_setting('test.app_org')::uuid,null,current_setting('test.app_branch')::uuid,current_setting('test.app_customer2')::uuid,current_setting('test.app_service')::uuid,current_setting('test.app_staff')::uuid,current_date+1,'10:00','11:00','scheduled','Adjacent')::text,true);
select results_eq($$select start_time,end_time from public.appointments where id=current_setting('test.app_adjacent')::uuid$$,$$select time'10:00',time'11:00'$$,'Back-to-back appointments do not overlap');
select lives_ok($$select public.set_business_module_state(current_setting('test.app_org')::uuid,'appointments',true,'{"slot_minutes":30,"prevent_staff_conflicts":false,"prevent_customer_conflicts":true}')$$,'Conflict behavior can be configured per Business');
select set_config('test.app2',public.save_appointment(current_setting('test.app_org')::uuid,null,current_setting('test.app_branch')::uuid,current_setting('test.app_customer2')::uuid,current_setting('test.app_service')::uuid,current_setting('test.app_staff')::uuid,current_date+1,'09:30','10:00','scheduled','Staff overlap allowed')::text,true);
select results_eq($$select count(*)from public.appointments where staff_id=current_setting('test.app_staff')::uuid and appointment_date=current_date+1 and start_time<'10:00'and end_time>'09:30'$$,$$select 2::bigint$$,'Disabling staff conflict prevention permits overlap');
select throws_ok($$select public.save_appointment(current_setting('test.app_org')::uuid,null,current_setting('test.app_branch')::uuid,current_setting('test.app_customer2')::uuid,current_setting('test.app_service')::uuid,current_setting('test.app_staff')::uuid,current_date+1,'09:45','10:15','scheduled','Customer conflict')$$,'P0001','Customer already has an overlapping appointment.','Configured customer conflict prevention rejects overlap');
select lives_ok($$select public.change_appointment_status(current_setting('test.app_org')::uuid,current_setting('test.app1')::uuid,'confirmed','Confirmed by mobile')$$,'Scheduled appointment can be confirmed');
select lives_ok($$select public.change_appointment_status(current_setting('test.app_org')::uuid,current_setting('test.app1')::uuid,'arrived','Checked in')$$,'Confirmed appointment can arrive');
select lives_ok($$select public.change_appointment_status(current_setting('test.app_org')::uuid,current_setting('test.app1')::uuid,'in_progress','Service started')$$,'Arrived appointment can start');
select lives_ok($$select public.change_appointment_status(current_setting('test.app_org')::uuid,current_setting('test.app1')::uuid,'completed','Service completed')$$,'In-progress appointment can complete');
select results_eq($$select status from public.appointments where id=current_setting('test.app1')::uuid$$,$$select 'completed'::text$$,'Lifecycle reaches completed status');
select throws_ok($$select public.change_appointment_status(current_setting('test.app_org')::uuid,current_setting('test.app1')::uuid,'confirmed','Reopen')$$,'P0001','Invalid appointment status transition.','Terminal appointments cannot be reopened');
select set_config('test.app_after',public.save_appointment(current_setting('test.app_org')::uuid,null,current_setting('test.app_branch')::uuid,current_setting('test.app_customer1')::uuid,current_setting('test.app_service')::uuid,current_setting('test.app_staff')::uuid,current_date+1,'09:00','09:30','scheduled','New booking after completion')::text,true);
select results_eq($$select count(*)from public.appointments where customer_id=current_setting('test.app_customer1')::uuid$$,$$select 2::bigint$$,'Completed records remain in customer history without blocking new bookings');
select lives_ok($$select public.change_appointment_status(current_setting('test.app_org')::uuid,current_setting('test.app2')::uuid,'no_show','Did not arrive')$$,'Scheduled appointment can be marked no-show');
select results_eq($$select count(*)from public.appointment_audit_history where appointment_id=current_setting('test.app1')::uuid$$,$$select 5::bigint$$,'Creation and every lifecycle transition generate audit history');
select results_eq($$select count(*)from public.appointments where organization_id=current_setting('test.app_org')::uuid and appointment_date=current_date+1$$,$$select 4::bigint$$,'Day and week schedules retain all appointment outcomes');
select * from finish();rollback;
